// src/pages/services/analytics.tsx
import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../../components/AppLink";
import Layout from "../../components/Layout";
import data from "../../data/data.json";
import type { Company } from "../../interfaces";
import images from "../../images";
import { useEffect } from "react";
import SEO from "../../components/seo";
import I18nHeadProvider from "../../components/I18nHeadProvider";

const info: Company = data[0];

type Chip = { chip: string };
type Card = { title: string; text: string };
type ListItem = { item: string };
type Step = { title: string; text: string };
type Faq = { q: string; a: string };

const AnalyticsServicePage: React.FC<PageProps> = () => {
  const { t, i18n } = useTranslation();
  const language = i18n.language;

      useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const heroChips = t("services.analytics.hero.chips", {
    returnObjects: true,
  }) as Chip[];

  const outcomes = t("services.analytics.sections.outcomes.items", {
    returnObjects: true,
  }) as Card[];

  const idealFor = t("services.analytics.sections.idealFor.items", {
    returnObjects: true,
  }) as ListItem[];

  const deliverables = t("services.analytics.sections.deliverables.items", {
    returnObjects: true,
  }) as ListItem[];

  const steps = t("services.analytics.sections.process.steps", {
    returnObjects: true,
  }) as Step[];

  const faq = t("services.analytics.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];

  const mailSubject = encodeURIComponent(
    t("services.analytics.hero.emailSubject") || "Inquiry about Analytics Service"
  );
  const mailto = `mailto:${info.email}?subject=${mailSubject}`;

  return (
    <Layout data={info}>
      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-4xl">
              {t("services.analytics.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("services.analytics.hero.subtitle")}
            </p>

            {/* CTAs */}
            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                              to="/contact/"
                              className="rounded-full bg-secondary px-5 py-2.5 text-light text-center">
                {t("services.analytics.hero.primaryCta")}
              </Link>

              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("services.analytics.hero.secondaryCta")}
              </a>
            </div>

            {/* Proof chips */}
            {Array.isArray(heroChips) && heroChips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {heroChips.map((c, idx) => (
                  <span
                    key={`${c.chip}-${idx}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {c.chip}
                  </span>
                ))}
              </div>
            ) : null}

            {/* Micro-proof line */}
            <p className="mx-auto mt-6 text-sm text-light/70 max-w-3xl">
              {language === "en"
                ? "Best for teams that run campaigns, update offers, and need reliable conversion tracking."
                : language === "fr"
                ? "Idéal pour les équipes qui mènent des campagnes, mettent à jour leurs offres et ont besoin d’un suivi fiable des conversions."
                : "Ideal para equipos con campañas y cambios frecuentes que necesitan tracking confiable de conversiones."}
            </p>
          </div>
        </div>
      </section>

      {/* OUTCOMES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.analytics.sections.outcomes.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(outcomes)
              ? outcomes.map((o, idx) => (
                  <div key={`${o.title}-${idx}`} className={styles.card}>
                    <h3 className="text-base sm:text-lg font-semibold text-light/90">
                      {o.title}
                    </h3>
                    <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                      {o.text}
                    </p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* IDEAL FOR */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.analytics.sections.idealFor.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {Array.isArray(idealFor)
                ? idealFor.map((x, idx) => (
                    <li key={`${x.item}-${idx}`} className={styles.card}>
                      <p className="text-sm sm:text-base text-light/80">
                        {x.item}
                      </p>
                    </li>
                  ))
                : null}
            </ul>
          </div>
        </div>
      </section>

      {/* DELIVERABLES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.analytics.sections.deliverables.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <div className={styles.card}>
              <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {Array.isArray(deliverables)
                  ? deliverables.map((d, idx) => (
                      <li key={`${d.item}-${idx}`}>{d.item}</li>
                    ))
                  : null}
              </ul>
            </div>

            {/* Helpful internal links */}
            <div className="mt-4 text-center text-sm text-light/70">
              <span className="mr-2">
                {language === "en"
                  ? "Related:"
                  : language === "fr"
                  ? "À lire aussi :"
                  : "Relacionado:"}
              </span>
              <Link to="/services/seo/" className="underline">
                {language === "en"
                  ? "SEO"
                  : language === "fr"
                  ? "SEO"
                  : "SEO"}
              </Link>
              <span className="mx-2">·</span>
              <Link to="/services/maintenance/" className="underline">
                {language === "en"
                  ? "Maintenance"
                  : language === "fr"
                  ? "Maintenance"
                  : "Mantenimiento"}
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* PROCESS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.analytics.sections.process.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(steps)
              ? steps.map((s, idx) => (
                  <div key={`${s.title}-${idx}`} className={styles.card}>
                    <div className="flex items-center gap-3">
                      <span className="inline-flex h-7 w-7 items-center justify-center rounded-full border border-black/10 bg-white text-sm font-semibold text-dark/70">
                        {idx + 1}
                      </span>
                      <h3 className="text-base sm:text-lg font-semibold text-light/90">
                        {s.title}
                      </h3>
                    </div>
                    <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                      {s.text}
                    </p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.analytics.sections.faq.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl space-y-3">
            {Array.isArray(faq)
              ? faq.map((x, idx) => (
                  <details key={`${x.q}-${idx}`} className={styles.card}>
                    <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                      {x.q}
                    </summary>
                    <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                      {x.a}
                    </p>
                  </details>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("services.analytics.sections.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("services.analytics.sections.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                              to="/contact/"
                              className="rounded-full bg-secondary px-5 py-2.5 text-light text-center">
                {t("services.analytics.sections.finalCta.primaryCta")}
              </Link>

              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("services.analytics.sections.finalCta.secondaryCta")}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <SEO
      data={info}
      titleKey="services.analytics.metaTitle"
      descriptionKey="services.analytics.metaDescription"
      pathname="/services/analytics/"
      schemaType="ProfessionalService"
    />
  </I18nHeadProvider>
);

export default AnalyticsServicePage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
    sectionWrapper: "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
    labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
    container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
    card :"rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
    cardTitle: "text-base sm:text-lg font-semibold text-light/90",
    cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
